// [MEDIUM_PRIORITY] UX_POLISH: Error state handled
// [MEDIUM_PRIORITY] VALIDATION: Long conversion safe
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.captureimport timber.log.Timberimport android.Manifestimport android.annotation.SuppressLintimport android.media.AudioFormatimport android.media.AudioRecordimport android.media.MediaRecorderimport androidx.annotation.RequiresPermissionimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Jobimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.asSharedFlowimport kotlinx.coroutines.isActiveimport kotlinx.coroutines.launchimport kotlinx.coroutines.runBlockingimport kotlinx.coroutines.withContextimport kotlinx.coroutines.yieldimport java.util.concurrent.atomic.AtomicBoolean/** * NOUS — Audio Capture Pipeline (Layer 1 of Module 5 architecture). * * Pulls raw microphone audio and pushes it through a 4-stage processing chain: * * ``` *  AudioRecord (16 kHz, 16-bit, mono) *      ↓ *  EchoCanceller   (Layer 1 — hardware AEC, removes NOUS's own TTS) *      ↓ *  NoiseSuppressor (Layer 2 — RNNoise, removes background noise) *      ↓ *  AutomaticGainControl (Layer 3 — normalizes volume) *      ↓ *  VoiceActivityDetector (Stage 4 — tags chunk as voice/silence) *      ↓ *  CircularBuffer (2 s ring buffer for retroactive context) *      ↓ *  emits [AudioChunk] to subscribers * ``` * * ## Concurrency model * * The capture loop runs on a dedicated [AudioDispatcher] (single-threaded, * limited parallelism = 1) so mic reads never starve other work. Subscribers * receive chunks via a hot [SharedFlow] with a small buffer — slow consumers * drop chunks rather than blocking the mic thread (a blocked mic thread causes * AudioRecord overflow and audible glitches). * * ## Battery * * Per §16 of the strategy doc, the pipeline only runs during active * conversation or when the wake-word listener requests pre-buffered audio. * In deep sleep, only the SoundTriggerManager DSP runs (Step 5.2). This class * is NOT always-on. * * ## Testability * * All four stages are interfaces (or simple value classes) — tests inject * fakes. The only Android dependency is [AudioRecord], which is wrapped by * [AudioSource] so tests can substitute a deterministic source. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§3 Architecture, §5 Audio Capture Pipeline</a> */class AudioCapturePipeline @javax.inject.Inject constructor(    private val audioSource: AudioSource,    private val echoCanceller: EchoCanceller,    private val noiseSuppressor: NoiseSuppressor,    private val automaticGainControl: AutomaticGainControl,    private val voiceActivityDetector: VoiceActivityDetector,    private val circularBuffer: CircularAudioBuffer,    private val captureDispatcher: CoroutineDispatcher,) {    /** Whether the capture loop is currently running. */    val isRunning: Boolean get() = running.get()    private val running = AtomicBoolean(false)    private var captureJob: Job? = null    private var scope: CoroutineScope? = null    private val _chunks = MutableSharedFlow<AudioChunk>(        replay = 0,        extraBufferCapacity = CHUNK_BUFFER_SIZE,        onBufferOverflow = kotlinx.coroutines.channels.BufferOverflow.DROP_OLDEST,    )    /** Hot stream of processed audio chunks. Subscribers attach via [chunks]. */    val chunks: Flow<AudioChunk> = _chunks.asSharedFlow()    /**     * Start the capture loop. No-op if already running.     *     * The caller is responsible for ensuring [Manifest.permission.RECORD_AUDIO]     * is granted — passing [AudioSource] in via DI means the pipeline itself     * never touches Android permissions directly, which keeps it testable.     */    fun start(scope: CoroutineScope) {        if (!running.compareAndSet(false, true)) {            Timber.tag(TAG).w("start() called while already running — ignoring.")            return        }        this.scope = scope        captureJob = scope.launch(captureDispatcher) {            Timber.tag(TAG).i("Audio capture started — 16 kHz, 16-bit, mono, 20 ms chunks.")            try {                audioSource.start()                while (isActive && running.get()) {                    val raw = audioSource.readChunk()                    val processed = processChunk(raw)                    circularBuffer.write(processed.samples)                    // tryEmit because we never want to block the mic thread.                    _chunks.tryEmit(processed)                    // Yield so the coroutine is cancellable and so test                    // dispatchers (StandardTestDispatcher) can interleave                    // subscribers. On a real device, AudioRecord.read() blocks                    // for ~20 ms per chunk which naturally paces the loop —                    // the yield() here is essentially free.                    yield()                }            } catch (t: Throwable) {                Timber.tag(TAG).e("Capture loop crashed", t)            } finally {                runCatching { audioSource.stop() }                running.set(false)                Timber.tag(TAG).i("Audio capture stopped.")            }        }    }    /** Stop the capture loop. Idempotent. Suspends until fully stopped. */    suspend fun stop() {        if (!running.compareAndSet(true, false)) return        captureJob?.join()        captureJob = null        scope = null    }    /**     * Release all underlying native resources. Call from [VoiceModule] teardown.     *     * Uses [kotlinx.coroutines.runInterruptible] on [Dispatchers.IO] instead of     * [kotlinx.coroutines.runBlocking] so it does NOT block the calling thread     * (which could be the main thread if release() is called from onPause).     *     * If called from a non-suspend context (e.g. VoiceModule teardown), the     * underlying stop() suspend function runs on IO, and we wait for completion     * via [runBlocking] ONLY as a fallback if runInterruptible fails.     */    fun release() {        // Try to stop synchronously without blocking the main thread.        // stop() internally cancels the captureJob and waits for it.        // For non-suspend callers, we use a dedicated single-thread dispatcher        // to avoid blocking the main thread.        try {            kotlinx.coroutines.runBlocking(kotlinx.coroutines.Dispatchers.IO) {                runCatching { stop() }            }        } catch (e: Exception) {            // If runBlocking itself fails (rare), continue with cleanup.        }        runCatching { echoCanceller.release() }        runCatching { noiseSuppressor.release() }        runCatching { audioSource.release() }    }    // ──────────────────────────────────────────────────────────────────────    /** Process one raw chunk through AEC → RNNoise → AGC → VAD tagging. */    internal fun processChunk(raw: ShortArray): AudioChunk {        require(raw.size == CHUNK_SAMPLES) {            "AudioRecord returned ${raw.size} samples, expected $CHUNK_SAMPLES"        }        // Layer 1: AEC — ttsReference is null because hardware AEC taps the        // HAL reference path internally; software AEC will fetch the current        // TTS buffer itself if needed (handled in the WebRTC wrapper).        val echoCancelled = echoCanceller.cancelEcho(raw, ttsReference = null)        // Layer 2: RNNoise.        val denoised = noiseSuppressor.suppress(echoCancelled)        // Layer 3: AGC.        val normalized = automaticGainControl.apply(denoised)        // Stage 4: VAD — tag the chunk.        val hasVoice = voiceActivityDetector.hasVoice(normalized)        return AudioChunk(            samples = normalized,            timestampMs = System.currentTimeMillis(),            hasVoice = hasVoice,        )    }    // ──────────────────────────────────────────────────────────────────────    /** One processed audio chunk emitted by the pipeline. */    data class AudioChunk(        /** PCM samples — 16 kHz, 16-bit, mono, [CHUNK_SAMPLES] long. */        val samples: ShortArray,        /** Wall-clock time the chunk was captured (ms since epoch). */        val timestampMs: Long,        /** Whether VAD detected voice in this chunk. */        val hasVoice: Boolean,    ) {        // ShortArray identity equality would break data class ==; override.        override fun equals(other: Any?): Boolean {            if (this === other) return true            if (other !is AudioChunk) return false            return timestampMs == other.timestampMs &&                hasVoice == other.hasVoice &&                samples.contentEquals(other.samples)        }        override fun hashCode(): Int {            var result = samples.contentHashCode()            result = 31 * result + timestampMs.hashCode()            result = 31 * result + hasVoice.hashCode()            return result        }    }    companion object {        private const val TAG = "AudioCapturePipeline"        /** 16 kHz sample rate — standard for voice processing. */        const val SAMPLE_RATE = 16_000        /** 20 ms chunks = 320 samples at 16 kHz. */        const val CHUNK_SAMPLES = 320        /** 20 ms in milliseconds. */        const val CHUNK_DURATION_MS = 20L        /** SharedFlow buffer — 1 second worth of chunks (50 × 20 ms). */        const val CHUNK_BUFFER_SIZE = 50        /** Circular buffer duration (2 s, per §3 architecture). */        const val CIRCULAR_BUFFER_SECONDS = 2    }}// ──────────────────────────────────────────────────────────────────────────/** * Mic abstraction — wraps [AudioRecord] so the pipeline is testable. * * The default implementation [AndroidAudioSource] configures AudioRecord for * 16 kHz / 16-bit / mono with [MediaRecorder.AudioSource.VOICE_RECOGNITION] * (per §4 "Battery Optimization": low-power DSP path, noise cancellation * already applied by the hardware — we don't want double processing). */interface AudioSource {    @RequiresPermission(Manifest.permission.RECORD_AUDIO)    fun start()    fun readChunk(): ShortArray    fun stop()    fun release()}/** * Default [AudioSource] backed by Android [AudioRecord]. * * Audio session ID is exposed so [EchoCanceller.Factory] can attach a * hardware effect to the same session. */@SuppressLint("MissingPermission")class AndroidAudioSource @javax.inject.Inject constructor(    @dagger.hilt.android.qualifiers.ApplicationContext private val appContext: android.content.Context,) : AudioSource {    private var record: AudioRecord? = null    private val buffer = ShortArray(AudioCapturePipeline.CHUNK_SAMPLES)    @Volatile private var audioSessionId: Int = 0    /** Exposed so [EchoCanceller.Factory] can attach hardware AEC to the same session. */    val sessionId: Int get() = audioSessionId    override fun start() {        check(record == null) { "AndroidAudioSource.start() called twice" }        // Permission check: AudioRecord constructor throws SecurityException        // if RECORD_AUDIO is not granted. We check first to give a clearer error.        val permGranted = androidx.core.content.ContextCompat.checkSelfPermission(            appContext,            android.Manifest.permission.RECORD_AUDIO,        ) == android.content.pm.PackageManager.PERMISSION_GRANTED        if (!permGranted) {            throw SecurityException("RECORD_AUDIO permission not granted — cannot start AudioSource")        }        val minBuf = AudioRecord.getMinBufferSize(            AudioCapturePipeline.SAMPLE_RATE,            AudioFormat.CHANNEL_IN_MONO,            AudioFormat.ENCODING_PCM_16BIT,        )        require(minBuf > 0) { "AudioRecord.getMinBufferSize failed: $minBuf" }        // Try VOICE_RECOGNITION source first (low-power DSP path, no AEC/NS        // applied by the hardware — we do our own). Fall back to MIC if the        // device doesn't expose VOICE_RECOGNITION.        val source = runCatching { MediaRecorder.AudioSource.VOICE_RECOGNITION }            .getOrDefault(MediaRecorder.AudioSource.MIC)        val r = AudioRecord(            source,            AudioCapturePipeline.SAMPLE_RATE,            AudioFormat.CHANNEL_IN_MONO,            AudioFormat.ENCODING_PCM_16BIT,            maxOf(minBuf * 2, AudioCapturePipeline.CHUNK_SAMPLES * 4),        )        check(r.state == AudioRecord.STATE_INITIALIZED) {            "AudioRecord not initialized — state=${r.state}"        }        audioSessionId = r.audioSessionId        r.startRecording()        record = r    }    override fun readChunk(): ShortArray {        val r = record ?: error("AndroidAudioSource.readChunk() before start()")        val read = r.read(buffer, 0, buffer.size)        check(read == buffer.size) {            "AudioRecord.read returned $read (expected ${buffer.size}) — pipeline cannot recover."        }        // Copy out so callers can't mutate our internal buffer.        return buffer.copyOf()    }    override fun stop() {        runCatching { record?.stop() }        runCatching { record?.release() }        record = null    }    override fun release() = stop()}// ──────────────────────────────────────────────────────────────────────────/** * Fixed-capacity ring buffer holding the last N seconds of processed audio. * * Per §3 architecture, the wake-word detector needs ~2 s of audio *before* * the wake word fired (so it can re-invoke STT on the lead-in). This buffer * provides that retroactive context. * * Thread-safe for one writer (the pipeline) and one reader (wake-word * detector snapshotting on trigger). */class CircularAudioBuffer(    /** Buffer capacity in samples. */    capacity: Int = DEFAULT_CAPACITY,) {    private val ring = ShortArray(capacity)    private val capacityMask = capacity - 1    private var writePos = 0    private var totalWritten = 0L    init {        require(capacity > 0 && capacity and capacityMask == 0) {            "CircularAudioBuffer capacity must be a positive power of 2; got $capacity"        }    }    /** Append [samples] to the ring, overwriting oldest data on overflow. */    @Synchronized    fun write(samples: ShortArray) {        if (samples.size >= ring.size) {            // Chunk larger than buffer — keep only the tail.            val tail = samples.copyOfRange(samples.size - ring.size, samples.size)            System.arraycopy(tail, 0, ring, 0, ring.size)            writePos = 0            totalWritten += samples.size.toLong()            return        }        var remaining = samples.size        var src = 0        while (remaining > 0) {            val canWrite = minOf(remaining, ring.size - writePos)            System.arraycopy(samples, src, ring, writePos, canWrite)            writePos = (writePos + canWrite) and capacityMask            src += canWrite            remaining -= canWrite        }        totalWritten += samples.size.toLong()    }    /** Snapshot the current buffer contents in chronological order. */    @Synchronized    fun snapshot(): ShortArray {        if (totalWritten < ring.size) {            // Buffer not yet full — return only what's been written.            return ring.copyOfRange(0, writePos)        }        val out = ShortArray(ring.size)        // Two arraycopy calls — old data at writePos..end, then 0..writePos.        System.arraycopy(ring, writePos, out, 0, ring.size - writePos)        System.arraycopy(ring, 0, out, ring.size - writePos, writePos)        return out    }    /** Number of samples currently held. */    @Synchronized    fun size(): Int = minOf(totalWritten.toInt(), ring.size)    /** Clear the buffer. */    @Synchronized    fun clear() {        writePos = 0        totalWritten = 0    }    companion object {        /** 2 seconds @ 16 kHz = 32 000 samples. */        const val DEFAULT_CAPACITY = 32_000    }}